import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        String firstLine = reader.readLine();
        String secondLine = reader.readLine();
        int n = Integer.parseInt(firstLine);
        String combined = secondLine + "_";

        boolean insideParenthesis = false, insideWord = false;
        int totalWordsCount = 0, currentWordSize = 0, maximumWordSize = 0;

        for (int i = 0; i <= n; i++) {
            char ch = combined.charAt(i);
            if (insideWord && (ch == '_' || ch == '(' || ch == ')')) {
                insideWord = false;
                if (insideParenthesis) {
                    totalWordsCount++;
                } else if (currentWordSize > maximumWordSize) {
                    maximumWordSize = currentWordSize;
                }
                if (ch == '(') {
                    insideParenthesis = true;
                }
                if (ch == ')') {
                    insideParenthesis = false;
                }
                currentWordSize = 0;
            } else if (!insideWord && !(ch == '_' || ch == '(' || ch == ')')) {
                insideWord = true;
                currentWordSize++;
            } else if (insideWord) {
                currentWordSize++;
            } else {
                if (ch == '(') {
                    insideParenthesis = true;
                } else if (ch == ')') {
                    insideParenthesis = false;
                }
            }
        }
        writer.printf("%d %d", maximumWordSize, totalWordsCount);
        writer.close();
    }
}
